const crypto = require('crypto');
const source = $json.body ?? $json;
const value = source.entry?.[0]?.changes?.[0]?.value;
const message = value?.messages?.[0];
const contact = value?.contacts?.[0];
const interactiveText = message?.interactive?.button_reply?.title ?? message?.interactive?.list_reply?.title;
const payload = message ? {
  wa_id: contact?.wa_id ?? message.from,
  message_id: message.id,
  message_type: message.type ?? 'unknown',
  text: message.text?.body ?? interactiveText ?? '',
  media_id: message.image?.id ?? message.document?.id ?? '',
  mime_type: message.image?.mime_type ?? message.document?.mime_type ?? '',
  file_name: message.document?.filename ?? ''
} : {
  wa_id: source.wa_id,
  message_id: source.message_id,
  message_type: source.message_type ?? 'text',
  text: source.text ?? '',
  media_id: source.media_id ?? '',
  mime_type: source.mime_type ?? '',
  file_name: source.file_name ?? ''
};
if (!payload.wa_id || !payload.message_id) throw new Error('Evento de WhatsApp sin wa_id o message_id');
const body = JSON.stringify(payload);
const timestamp = Math.floor(Date.now() / 1000).toString();
const nonce = crypto.createHash('sha256').update(payload.message_id).digest('hex').slice(0, 32);
const secret = $env.N8N_SHARED_SECRET;
if (!secret) throw new Error('Falta N8N_SHARED_SECRET');
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${nonce}.${body}`).digest('hex');
return [{ json: { requestBody: payload, rawBody: body, headers: { timestamp, nonce, signature } } }];
